import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.BiXHgXAn.js";const m=JSON.parse(`{"title":"Task documentation for coding agents","description":"A compact map of Task's documentation, plus the execution semantics that are easiest to get wrong when generating a Taskfile.","frontmatter":{"title":"Task documentation for coding agents","description":"A compact map of Task's documentation, plus the execution semantics that are easiest to get wrong when generating a Taskfile.","outline":"deep"},"headers":[],"relativePath":"agents.md","filePath":"next/agents.md"}`),i={name:"agents.md"};function n(r,e,d,c,l,h){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="task-documentation-for-coding-agents" tabindex="-1">Task documentation for coding agents <a class="header-anchor" href="#task-documentation-for-coding-agents" aria-label="Permalink to &quot;Task documentation for coding agents&quot;">​</a></h1><p>Task is a cross-platform task runner and build tool. Its configuration file is normally named <code>Taskfile.yml</code>, and new files should use schema version <code>3</code>.</p><p>Every page linked below is also available as raw Markdown: append <code>.md</code> to its URL. The curated index is at <a href="/llms.txt">/llms.txt</a> and the full corpus at <a href="/llms-full.txt">/llms-full.txt</a>.</p><h2 id="where-to-look" tabindex="-1">Where to look <a class="header-anchor" href="#where-to-look" aria-label="Permalink to &quot;Where to look&quot;">​</a></h2><ul><li><a href="./docs/getting-started">Quick Start</a>: the shape of a Taskfile.</li><li><a href="./docs/reference/schema">Taskfile Schema</a>: the source of truth for keys, types and accepted values. Check here before assuming a field exists.</li><li><a href="./docs/reference/cli">CLI</a>: commands, flags and exit codes.</li><li><a href="./docs/reference/templating">Templating</a>: every template function and special variable. Check here before inventing one.</li><li><a href="./docs/guide/">Guide</a>: task definitions, inputs, execution and shared Taskfiles.</li><li><a href="./docs/guide/errors-and-cleanup">Errors and cleanup</a>: failure handling and <code>defer</code>.</li><li><a href="./docs/guide/secret-variables">Secret variables</a>: masking and its limits.</li><li><a href="./docs/guide/variables#resolution-order">Resolution order</a> and <a href="./docs/guide/dependencies#task-dependencies">Task dependencies</a>: for when the behaviour matters more than the procedure.</li></ul><h2 id="semantics-that-are-easy-to-get-wrong" tabindex="-1">Semantics that are easy to get wrong <a class="header-anchor" href="#semantics-that-are-easy-to-get-wrong" aria-label="Permalink to &quot;Semantics that are easy to get wrong&quot;">​</a></h2><ol><li><code>vars</code> are not exported to <code>cmds</code>: use templates to read them there. Dynamic variables (<code>sh:</code>) also receive previously resolved scalar variables in their shell environment. <code>env</code> is exported to commands. Root-level <code>env</code> also participates in templates; task-level <code>env</code> does not. A template keeps any value resolved from other sources, or renders empty if none exists.</li><li>A constant in a task&#39;s own <code>vars:</code> overrides the command line. Put the default in global <code>vars:</code>, or use a template such as <span><code>NAME: &#39;{{.NAME | default &quot;World&quot;}}&#39;</code></span> to preserve caller input.</li><li>The included Taskfile&#39;s own <code>vars:</code> are applied after <code>includes.vars</code>. A constant overrides the include&#39;s value; a self-referencing template with <code>default</code> can preserve it.</li><li>Everything in <code>deps</code> may run concurrently and in any order. A <code>task:</code> reference inside <code>cmds</code> runs at its position and blocks the next command. If order matters, use <code>cmds</code>.</li><li>Each command runs in its own shell. Nothing carries over between them, not <code>cd</code> and not an exported variable. Use Task&#39;s <code>dir:</code> and <code>env:</code> instead.</li><li>A template renders text. Use <code>ref:</code> to pass an array or a map without flattening it to a string.</li><li>A passing <code>status:</code> means the task is already up to date and is skipped. A failing <code>preconditions:</code> means the task must not run at all. They are not interchangeable.</li><li><code>defer:</code> commands run in reverse order of declaration, and run whether the task succeeded or failed.</li><li>Remote Taskfiles execute code from wherever they are fetched. See <a href="./docs/remote-taskfiles">Remote Taskfiles</a> for the trust and checksum rules.</li><li>Portability is about every command inside a task, not just Task itself. A task is only cross-platform if its commands are.</li></ol><h2 id="before-writing-a-taskfile" tabindex="-1">Before writing a Taskfile <a class="header-anchor" href="#before-writing-a-taskfile" aria-label="Permalink to &quot;Before writing a Taskfile&quot;">​</a></h2><ul><li>Confirm the feature exists in the schema for the version in use.</li><li>Prefer plain, readable tasks over dense templating.</li><li>Use <code>deps</code> only where concurrent execution is actually correct.</li><li>Never embed credentials. Read them from the environment or a secret manager. <code>secret: true</code> masks a value in Task&#39;s own logs, but it only works on <code>vars:</code>, not on <code>env:</code>, and it never masks what a command itself prints. Treat it as one less place a secret is echoed, not as protection.</li><li>Give tasks a <code>desc:</code> so they show up in <code>task --list</code>, and validate inputs with <code>requires:</code> or <code>preconditions:</code>.</li></ul>',9)])])}const f=a(i,[["render",n]]);export{m as __pageData,f as default};
